INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AIANOM_CLUE_CAT', 5, 'L-Gate Insight', 'We have learned of a mysterious star cluster somewhere just beyond the periphery of our galaxy. It can only be accessed through L-Gates, artificial subspace portals found in certain systems.
These Gateways have been deliberately disabled by someone, and for now we lack the necessary insight into the subspace mechanics that govern their use to lift the lockdown.', '[{"event": "aianom.11", "name": null}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AIANOM_LUMP_CAT', 1, 'Orbital Debris', 'Sensors register potentially interesting entities in orbit of .', '[{"event": "aianom.1", "name": null}, {"event": "aianom.2", "name": null}, {"event": "aianom.3", "name": null}, {"event": "aianom.4", "name": null}, {"event": "aianom.5", "name": null}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AIANOM_MININGDEPO_CAT', 1, 'Surface Pings', 'Sensors register potential finds on the surface of .', '[{"event": "aianom.6", "name": null}, {"event": "aianom.7", "name": null}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AIANOM_RESEARCHDEPO_CAT', 2, 'Surface Pings', 'Sensors register potential finds on the surface of .', '[{"event": "aianom.8", "name": null}, {"event": "aianom.9", "name": null}, {"event": "aianom.10", "name": null}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('ALPHA_CENTAURI_CAT', 1, 'Stasis', '''s peculiar orbit around its red dwarf star renders the planet tidally locked, and potentially worthy of further investigation.', '[{"event": "anomaly.6745", "name": null}, {"event": "anomaly.6750", "name": null}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('ANCREL_ARC_CAT', 3, 'Alien Site', 'Check out the alien signal', '[{"event": "ancrel.107", "name": "Finding the Truth"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('ANCREL_MECHANO_CAT', 5, 'A Planetary Machine', 'This planet is covered from pole to pole in rusting, ancient machinery, much of which is itself covered in an unidentified, organic tissue. What manner of creatures could have built this technological curiosity, and what happened to them?', '[{"event": "ancrel.2050", "name": "Planet-Wide Machinery"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('ANCREL_RUBRICATOR_CAT', 4, 'Weapon Trails', 'Faint traces of weapon radiation indicative of a military spacecraft have been detected on .', '[{"event": "ancrel.4010", "name": "Alien Spacecraft"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('ARID_PLANET_CAT', 3, 'Arid Wastes', 'The is not the most welcoming of places, but if our initial scans are any indication it could hold some valuable resources.', '[{"event": "anomaly.4170", "name": "Volatile Resources"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('ARID_SENSOR_CAT', 6, 'Arid and Abandoned', 'We have detected something out of the ordinary on the arid . It seems like somebody has been here before us. Further investigation is needed.', '[{"event": "anomaly.4080", "name": "Abandoned Sensor Array"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('ASTRAL_SCAR_CAT', 6, 'Astral Scar', 'We have discovered an anomalous rift in space and time. The closer we get, the less the known laws of physical relativity hold purchase.
Studying this phenomenon could very well push our scientific understanding of the mechanics of the universe to a higher level.', '[{"event": "astral_planes.6000", "name": "Astral Scar"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AST_CLUSTER_CAT', 3, 'Mineral Cluster', 'An unusually deliberate, geometric configuration of minerals drifts through the debris belt by , and is possibly of alien origin.', '[{"event": "anomaly.3000", "name": "Careless Pawing"}, {"event": "anomaly.3005", "name": "Gilded Cage"}, {"event": "anomaly.3085", "name": "The Prince"}, {"event": "anomaly.3010", "name": "Crystal Codex"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AST_CRATER_CAT', 1, 'Dustbowl', 'is home to a number of exquisite impact craters. However, something breaks the visual uniformity in one of the larger craters...', '[{"event": "anomaly.265", "name": "Alien Drag Racing"}, {"event": "anomaly.270", "name": "Fender Bender"}, {"event": "anomaly.275", "name": "Abandoned Thrusting"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AST_DEBRIS_FIELD_1_CAT', 3, 'Debris Field', 'Sensors report a number of possible points of interest within the dense debris field surrounding .', '[{"event": "anomaly.95", "name": "Important to Someone Else"}, {"event": "anomaly.100", "name": "Catching up with a Pioneer"}, {"event": "anomaly.105", "name": "Old-Timey Tunes"}, {"event": "anomaly.3040", "name": "Pirate Exiles"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AST_GEAR_CAT', 6, 'Astonishing Asteroids', 'Observing the massive asteroid , we have found...
Something. Further investigation is warranted.', '[{"event": "anomaly.4065", "name": "Mining Your Own Business"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AST_ILLICIT_DARK_CAT', 7, 'Radiating Asteroid', 'periodically spews an alarmingly eclectic mix of particles and radiation into the void.', '[{"event": "anomaly.155", "name": "Illicit Matter"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AST_MINING_CAT', 2, 'Mind the Minerals', 'Initial analysis of the asteroid''s composition points towards potentially interesting finds.', '[{"event": "anomaly.4005", "name": "Fragments of Life"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AST_SHRINE_1_CAT', 3, 'An Asteroid, Carved', 'has been partially hollowed out and carved with exquisite precision. There is something familiar about the lines and curves etched into the rock...', '[{"event": "anomaly.140", "name": "Familiar Shrine"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('AST_WAVELENGTHS_1_CAT', 1, 'Asteroid Waves', 'The asteroid is emitting some form of radiation in controlled bursts. Is someone - something - trying to communicate with us?', '[{"event": "anomaly.75", "name": "Rock Brain"}, {"event": "anomaly.115", "name": "Cells"}, {"event": "anomaly.130", "name": "Gravity Crush"}, {"event": "anomaly.3065", "name": "Illicit Communications"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('ATM_ANOMALY_CAT', 3, 'Atmospheric Anomaly', 'Atmospheric readings from do not match simulated projections.', '[{"event": "anomaly.225", "name": "Swirling Shadows"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('BACKWARDS_ORBIT_CAT', 3, 'Backwards Orbit', 'orbits its star in the reverse direction compared to the other planets in the system, suggesting it did not form here at the same time as its companion celestial bodies.
Further investigation is needed to understand this planet''s origins.', '[{"event": "extreme_frontiers.390", "name": null}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('BARR_BASE_CAT', 5, 'On the Barren Plains', 'A cursory scan of the planet''s surface reveals a weak signal pulsing into the darkness of space.', '[{"event": "anomaly.185", "name": "Limbo"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('BAR_COLONY_CAT', 6, 'Looking Down', 'Optical sensors isolate a cluster of shapes on the barren surface of that could be buildings.', '[{"event": "anomaly.285", "name": "Unusual Tectonics"}, {"event": "anomaly.3015", "name": "Alien Barracks"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('BLACK_CLOUDS_CAT', 5, 'Black Clouds', 'Thick black clouds have been observed in ''s atmosphere, moving in erratic patterns independent of planetary wind speed or direction. They appear only briefly on our imaging scans and always at the same point in the planet''s day-night cycle.', '[{"event": "extreme_frontiers.180", "name": null}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('BLACK_HOLE_INSTABLE_CAT', 5, 'Black Hole Instability', 'Our scanners have detected significant deviations from the expected physical properties of the black hole in the system. Its gravitational forces are unpredictable, resulting in noticeable temporal inconsistencies from one point in space to another.', '[{"event": "astral_planes.6020", "name": "Black Hole Instability"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
