               VALUES ('life_toxic_category', 2, 'Life Signs', 'Despite the toxic content and high pressure of this ''s atmosphere, strong life signs have been detected coming from its surface.', '[{"event": "anomaly.690", "name": "Ammonia Biosphere"}, {"event": "anomaly.6895", "name": "Toxic Biological Industry"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('living_metal_category', 7, 'Peculiar Crater', 'A large impact crater has been discovered that does not seem to be a natural occurrence.', '[{"event": "anomaly.2576", "name": "A New Metal"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('lost_soul_cat', 2, 'Lost Soul', 'We have found a heavily damaged bipedal robot floating in space. We do not understand its energy source, but we may be able to retrieve information from its memory.', '[{"event": "anomaly.6786", "name": "Lost Soul"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
