INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('moon_gasgiant_category', 1, 'Promising Moon', 'One of the small moonlets orbiting this gas giant has been identified as a promising mining site. A more thorough survey will have to be conducted to determine whether a mining operation would be feasible or not.', '[{"event": "anomaly.340", "name": "Precious Moon"}, {"event": "anomaly.6840", "name": "Too Few Sheep"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
