INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('mysterious_ringing_category', 4, 'Mysterious Ringing', 'Our scientists have detected regular radio wave spikes from a single point on . They appear to coincide with the time at which the source of the signal crosses from night into day.', '[{"event": "infernals.3210", "name": "Mysterious Ringing"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
