INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('object_uninhabitable_category', 2, 'Unidentified Object', 'A small rectangular object on the surface of this is deflecting all scanning beams like a mirror. Our sensors are unable to determine its material composition.', '[{"event": "anomaly.2540", "name": "Alien Mural"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
