INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('on_solar_sails_cat', 2, 'On Solar Sails', 'We have found the wreckage of an archaic spaceship with an unusual design. We''re not quite sure how its propulsion system works.', '[{"event": "anomaly.7020", "name": "On Solar Sails"}]');
INSERT OR REPLACE INTO anomaly_category (key, level, name, description, outcomes_json)
               VALUES ('origin_asteroid_category', 1, 'Unknown Origin', 'The material composition of this asteroid differs significantly from its neighbors. It likely has a different origin than the other bodies of this asteroid belt, and should be investigated more closely.', '[{"event": "anomaly.1", "name": "Coprolite Asteroid"}, {"event": "anomaly.15", "name": "Asteroid Fossils"}, {"event": "distar.225", "name": "Junk Ball"}]');
