INSERT OR REPLACE INTO static_modifier (key, name, description, tooltip) VALUES ('behemoth_mutation_a', 'Behemoth Mutations: Aggression', 'Oversized muscles make for devastating attacks.', 'Behemoth Ship Fire Rate: +$@behemoth_mutation_a_fire_rate_mult|0%$ Behemoth Armor Hit Points: $@behemoth_mutation_a_armor_mult|0%$ Behemoth Sublight Speed: $@behemoth_mutation_a_speed_mult|0%$');
