INSERT OR REPLACE INTO static_modifier (key, name, description, tooltip) VALUES ('behemoth_mutation_c', 'Behemoth Mutations: Agility', 'A more powerful set of subspace glands makes our behemoths more nimble.', 'Behemoth Sublight Speed: +$@behemoth_mutation_c_speed_mult|0%$ Behemoth Evasion Chance: +$@behemoth_mutation_c_evasion_mult|0%$');
INSERT OR REPLACE INTO static_modifier (key, name, description, tooltip) VALUES ('behemoth_mutation_corpo', 'Behemoth Merchandising', 'Our shareholders were a little preoccupied with the Behemoth Project, but the increased dividends quickly won them over.', 'Monthly Trade: +$@behemoth_mutation_corpo_trade_produces_mult|0%$ per Behemoth');
INSERT OR REPLACE INTO static_modifier (key, name, description, tooltip) VALUES ('behemoth_mutation_cyber', 'Behemoth Mutations: Cybernetics', 'To harness the furious power of behemoths, we will develop the most advanced piece of cyberware to ever exist.', 'Our Behemoths gain a 25% chance to resist their rage. While raging, they get +$@behemoth_cyber_rage_fire_rate_mult|0%$ Fire Rate, +$@behemoth_cyber_rage_shield_penetration_add|0%$ Armor Penetration and +$@behemoth_cyber_rage_armor_penetration_add|0%$ Shield Penetration');
INSERT OR REPLACE INTO static_modifier (key, name, description, tooltip) VALUES ('behemoth_mutation_psi', 'Behemoth Mutations: Barrier', 'While behemoths are not connected to the Shroud, we have raised them to be receptive enough to our telepaths that they can utilize defensive psionic barriers.', NULL);
INSERT OR REPLACE INTO static_modifier (key, name, description, tooltip) VALUES ('behemoth_mutation_psi_2', 'Behemoth Mutations: Psionics', 'O Beasts, take our power!', 'Behemoth Daily Shield Regen: +$@behemoth_mutation_psi_shield_regen_add_perc|0%$ per 100 Telepaths or Transference Volunteer Behemoth Shield Hardening: +$@behemoth_mutation_psi_shield_hardening_add|0%$ per 100 Telepaths or Transference Volunteer Current Number of 100 Employed Telepaths and Transference Volunteer:');
INSERT OR REPLACE INTO static_modifier (key, name, description, tooltip) VALUES ('behemoth_mutation_synth', 'Behemoth Mutations: Resilience', 'Melding alloys and chitin creates a multilayered carapace that will keep vital organs safe.', 'Behemoth Armor Hit Points: +$@behemoth_mutation_synth_armor_mult|0%$ Behemoth Daily Armor Regen: +$@behemoth_mutation_synth_armor_regen_add_perc|0%$');
