INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('war_philosophy', 'War Philosophy', 'War is a complex matter, war between stellar nations even more so. How we approach armed conflict is of critical importance to external affairs.', 'diplomacy,military', '{"op":"or","args":[{"leaf":"is_country_type","value":"default"},{"leaf":"is_country_type","value":"fallen_empire"},{"leaf":"is_country_type","value":"awakened_fallen_empire"}]}', '{"leaf":"is_at_war","value":"no"}', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('unrestricted_wars', 'war_philosophy', 'Unrestricted Wars', 'War is a dish best served frequently, and to those who will not cook for themselves.
No restrictions on claiming systems', NULL, '{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_pacifist"},{"leaf":"has_ethic","value":"ethic_fanatic_pacifist"},{"leaf":"has_valid_civic","value":"civic_inwards_perfection"},{"leaf":"has_civic","value":"civic_crusader_spirit"}]}]}', 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('liberation_wars', 'war_philosophy', 'Liberation Wars', 'We must further our own interests, even when they run contrary to the interests of others.
Claiming others'' systems is only allowed during defensive wars or against Gestalt Consciousness empires
Unlocks the ''Ideology'' Casus Belli on all empires with differing Ethics', '{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"}]}', '{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_fanatic_pacifist"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"}]}]}', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('no_wars', 'war_philosophy', 'Defensive Wars', 'Violence is a last resort to ensure the integrity of our nation.
Claiming of systems is only allowed during defensive wars', NULL, '{"op":"not","args":[{"op":"or","args":[{"leaf":"is_fanatic_militarist","value":"yes"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"},{"leaf":"has_valid_civic","value":"civic_machine_terminator"},{"leaf":"has_civic","value":"civic_crusader_spirit"}]}]}', 2);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('war_doctrine', 'War Doctrine', 'There are many ways to prosecute a war to a successful conclusion. We must choose the doctrine that best plays to our strengths and weaknesses.', 'military', '{"op":"or","args":[{"op":"and","args":[{"leaf":"is_country_type","value":"default"},{"op":"or","args":[{"leaf":"has_tradition","value":"tr_supremacy_finish"},{"leaf":"has_country_flag","value":"hunger_accord"}]}]},{"leaf":"is_mercenary","value":"yes"},{"leaf":"is_country_type","value":"enclave_mercenary"},{"leaf":"has_menace_perk","value":"menp_defender_crisis_damage_4"}]}', NULL, 2);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('defense_in_depth_doctrine', 'war_doctrine', 'Defense in Depth', 'Let the enemy come to us. We shall fight them for every planet, every moon, every asteroid that lies within our space. We shall never surrender.', NULL, '{"op":"or","args":[{"op":"and","args":[{"leaf":"is_country_type","value":"default"},{"leaf":"has_tradition","value":"tr_supremacy_finish"}]},{"leaf":"is_country_type","value":"enclave_mercenary"}]}', 0);
