                   potential_json, valid_json, sort_order) VALUES ('force_preservation_doctrine', 'war_doctrine', 'Force Preservation', 'There is a time and place to give your life in service of a cause. Until the time comes, we cannot afford to squander the lives of our people.', NULL, '{"leaf":"has_menace_perk","value":"menp_defender_crisis_damage_4"}', 7);
