INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('subjugation_war_terms', 'Subjugation War Terms', 'Our stance regarding the initial Agreement Terms for Vassals or Subsidiaries we subjugate via war.', 'diplomacy', '{"op":"and","args":[{"leaf":"is_subject","value":"no"},{"op":"or","args":[{"leaf":"is_country_type","value":"default"},{"leaf":"is_country_type","value":"fallen_empire"},{"leaf":"is_country_type","value":"awakened_fallen_empire"}]}]}', NULL, 3);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('oppressive_terms', 'subjugation_war_terms', 'Oppressive Vassalage', 'Those we subjugate are inferior to us, we tolerate them only because they remain silent and shower us with their pathetic gifts.
Initial Vassal Agreement Terms: Integration Permitted, Limited Diplomacy, Expansion Prohibited, Joins Overlord Wars: All, Joins Subject Wars: Defensive, Subject Holdings Limit: 1', '{"leaf":"is_megacorp","value":"no"}', NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('balanced_terms', 'subjugation_war_terms', 'Balanced Vassalage', 'We believe in treating our subjects fairly. Perhaps in time, they will see the wisdom of our ways and the errors of theirs.
Initial Vassal Agreement Terms: Integration Prohibited, Restricted Voting, Expansion Regulated, Joins Overlord Wars: Defensive, Joins Subject Wars: Defensive, Subject Holdings Limit: 1', '{"leaf":"is_megacorp","value":"no"}', NULL, 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('benevolent_terms', 'subjugation_war_terms', 'Benevolent Vassalage', 'Our subjects are as much part of us as we are of them, their success is our victory, and we shall move forward as one.
Initial Vassal Agreement Terms: Integration Prohibited, Independent Diplomacy, Expansion Permitted, Joins Overlord Wars: Defensive, Joins Subject Wars: Defensive, Subject Holdings Limit: 1', '{"leaf":"is_megacorp","value":"no"}', NULL, 2);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('oppressive_corporate_terms', 'subjugation_war_terms', 'Hostile Takeover', 'The pathetic attempt to block this acquisition has failed; no matter their convictions, in the end, everyone has a price.
Initial Subsidiary Agreement Terms: Integration Prohibited, Restricted Voting, Expansion Regulated, Basic Resource Taxes: 45%, Advanced Resource Taxes: 15%, Joins Overlord Wars: All, Joins Subject Wars: Defensive, Subject Holdings Limit: 1
This is an Oppressive Subjugation Policy.', '{"leaf":"is_megacorp","value":"yes"}', NULL, 3);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('balanced_corporate_terms', 'subjugation_war_terms', 'Standard Acquisition', 'With a satisfactory deal in place, both parties can now get back to work.
Initial Subsidiary Agreement Terms: Integration Prohibited, Restricted Voting, Expansion Regulated, Basic Resource Taxes: 30%, Joins Overlord Wars: Defensive, Joins Subject Wars: Defensive, Subject Holdings Limit: 1
This is a Balanced Subjugation Policy.', '{"leaf":"is_megacorp","value":"yes"}', NULL, 4);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('benevolent_corporate_terms', 'subjugation_war_terms', 'Negotiated Synergy', 'The best deals benefit both parties; like life itself, business flourishes in harmony.
Initial Subsidiary Agreement Terms: Integration Prohibited, Independent Diplomacy, Expansion Permitted, Basic Resource Taxes: 30%, Joins Overlord Wars: Defensive, Joins Subject Wars: Defensive, Subject Holdings Limit: 1
This is a Benevolent Subjugation Policy.', '{"leaf":"is_megacorp","value":"yes"}', NULL, 5);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('orbital_bombardment', 'Orbital Bombardment', 'Orbital Bombardment allows us to destroy armies on a planet from space. More punitive orbital bombardment stances can also destroy buildings and kill population.', 'military', '{"op":"or","args":[{"leaf":"is_country_type","value":"default"},{"leaf":"is_country_type","value":"vol"}]}', NULL, 4);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('orbital_bombardment_selective', 'orbital_bombardment', 'Selective', 'Allows only the bombardment of identified military targets, while keeping civilian casualties to a minimum.
Can only use ''Selective'' orbital bombardment stance.', NULL, '{"op":"not","args":[{"leaf":"has_event_chain","value":"contract_raid_planet_chain"}]}', 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('orbital_bombardment_indiscriminate', 'orbital_bombardment', 'Indiscriminate', 'Allows the full use of all orbital weaponry, with no regards to life on the surface.
Allows ''Indiscriminate'' orbital bombardment stance.', NULL, '{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_pacifist"},{"leaf":"has_ethic","value":"ethic_fanatic_pacifist"}]}]}', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('orbital_bombardment_armageddon', 'orbital_bombardment', 'Armageddon', 'Allows the full use of all orbital weaponry, with no regards to life on the planet itself. Utter annihilation is the goal.
Allows ''Indiscriminate'' and ''Armageddon'' orbital bombardment stances.', '{"op":"or","args":[{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"has_valid_civic","value":"civic_machine_terminator"}]}', NULL, 2);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('orbital_bombardment_devastation', 'orbital_bombardment', 'Devastation', 'Allows the full use of all orbital weaponry, with the express aim of devastating the landscape.
Allows ''Devastation'' orbital bombardment stance.', '{"op":"or","args":[{"leaf":"has_valid_civic","value":"civic_scorched_earth"},{"leaf":"has_valid_civic","value":"civic_hive_scorched_earth"}]}', NULL, 3);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('orbital_bombardment_accept_surrender', 'Orbital Surrender Acceptance', 'This policy controls whether or not we allow enemy planets to surrender control to our fleets during Orbital Bombardment.', 'military', '{"leaf":"is_homicidal","value":"no"}', NULL, 5);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('orbital_bombardment_surrender_forbidden', 'orbital_bombardment_accept_surrender', 'Prohibited', 'There will be no surrender, Orbital Bombardment will continue indefinitely.
Planetary Control of Enemy Planets will only be gained by invading the planet with Ground Troops.', NULL, NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('orbital_bombardment_surrender_allowed', 'orbital_bombardment_accept_surrender', 'Allowed', 'Foreign citizens have the right to surrender.
We will gain occupation of Enemy Planets from Orbital Bombardment of planets without Defensive Armies if they choose to surrender.', '{"leaf":"is_homicidal","value":"no"}', NULL, 1);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('interference', 'Pre-FTL Interference', 'We can set policies regulating our interactions with pre-FTL empires.', 'diplomacy', '{"leaf":"has_met_primitives","value":"yes"}', NULL, 6);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('interference_not_allowed', 'interference', 'Non-Interference', 'It is not our place to influence the development of another society. Watch, but do not interfere.
Pre-FTL civilizations may only be passively observed
Cannot target Pre-FTL Civilizations with Espionage operations
Cannot reveal our presence to Pre-FTL Civilizations
Cannot invade Pre-FTL Civilizations', NULL, '{"op":"or","args":[{"leaf":"any_agreement","value":"scope"},{"leaf":"is_active_resolution","value":"resolution_pre_ftl_stances_non_interference"},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_fanatic_xenophobe"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"},{"leaf":"has_valid_civic","value":"civic_machine_terminator"}]}]}]}', 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('interference_subtle', 'interference', 'Subtle Interference', 'We can nudge their development in the right direction, but our touch must remain subtle.
Pre-FTL civilizations may only be passively observed
Can target Pre-FTL Civilizations with certain Espionage operations
Can only reveal our presence to Pre-FTL Civilizations with High Awareness
Cannot invade Pre-FTL Civilizations', NULL, '{"op":"or","args":[{"leaf":"any_agreement","value":"scope"},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_fanatic_xenophobe"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"},{"leaf":"has_valid_civic","value":"civic_machine_terminator"}]}]}]}', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('interference_active', 'interference', 'Active Interference', 'To unlock the secrets of the universe, any subject of interest must be made freely available for study.
Pre-FTL civilizations may be passively observed or actively studied
Can target Pre-FTL Civilizations with all Espionage operations
Can reveal our presence to Pre-FTL Civilizations
Cannot invade Pre-FTL Civilizations', NULL, '{"op":"not","args":[{"op":"or","args":[{"leaf":"any_agreement","value":"scope"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"}]}]}', 2);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('interference_aggressive', 'interference', 'Aggressive Interference', 'The strong hold dominion over the weak. The fate of less developed societies is ours to command.
Pre-FTL civilizations are subject to active study and Aggressive Observation
Can target Pre-FTL Civilizations with certain Espionage operations
Can reveal our presence to Pre-FTL Civilizations
Can invade Pre-FTL Civilizations', NULL, '{"op":"and","args":[{"op":"not","args":[{"leaf":"any_agreement","value":"scope"}]},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_pacifist"},{"leaf":"has_ethic","value":"ethic_fanatic_pacifist"},{"leaf":"has_ethic","value":"ethic_xenophile"},{"leaf":"has_ethic","value":"ethic_fanatic_xenophile"},{"leaf":"has_valid_civic","value":"civic_machine_exploration_protocol"}]}]}]}', 3);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('enlightenment', 'Pre-FTL Enlightenment', 'Our technological advances could potentially be shared with more pre-FTL societies, opening up new horizons for them to explore.', 'diplomacy', '{"leaf":"has_met_primitives","value":"yes"}', NULL, 7);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('enlightenment_not_allowed', 'enlightenment', 'Prohibited', 'This society is not ready to grasp the wonders we have discovered. Exposing the truth too quickly can entail enormous risks for everyone involved.
May Not Enlighten Pre-FTL Civilizations', NULL, NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('enlightenment_covert_only', 'enlightenment', 'Covert Only', 'Revealing our existence to pre-FTL civilizations would alter the natural course of their development. We should help them, but without revealing our presence.
May Only Enlighten Pre-FTL Civilizations through Espionage', NULL, '{"op":"and","args":[{"op":"not","args":[{"leaf":"has_policy_flag","value":"interference_not_allowed"}]},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_fanatic_xenophobe"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"},{"leaf":"has_valid_civic","value":"civic_machine_terminator"}]}]}]}', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('enlightenment_allowed', 'enlightenment', 'Allowed', 'By sharing our knowledge, we can actively encourage less advanced societies to take their rightful place in the galactic community.
May Enlighten Pre-FTL civilizations through both Espionage and Diplomatic actions', NULL, '{"op":"and","args":[{"op":"not","args":[{"leaf":"has_policy_flag","value":"interference_not_allowed"}]},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_fanatic_xenophobe"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"},{"leaf":"has_valid_civic","value":"civic_machine_terminator"}]}]}]}', 2);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('resettlement', 'Resettlement', 'This policy controls whether or not we are allowed to forcibly relocate Pops between planets.', 'society', '{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"}]}', NULL, 8);
INSERT INTO policy_option (key, policy_key, name, description,
