INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('appropriation', 'Land Appropriation', 'This policy controls whether or not newly acquired planets should have some of their land appropriated from non-citizen species.', 'society', '{"op":"and","args":[{"leaf":"has_comms_with_alien_empire","value":"yes"},{"leaf":"is_nomadic","value":"no"}]}', NULL, 9);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('appropriation_not_allowed', 'appropriation', 'Prohibited', 'The land that our empire controls belongs to all of its inhabitants.
Conquered planets will have their populations preserved as-is.', NULL, NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('appropriation_allowed', 'appropriation', 'Allowed', 'The land that the lesser species are not properly utilizing can be put to greater use by their betters.
Colonies conquered from non-citizen species will have up to 500 Pops displaced and replaced with citizens from our other colonies.', NULL, NULL, 1);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('leader_enhancement', 'Leader Enhancement', 'The burden of Empire can be crushing, and we need to make a decision on how future leaders may best be prepared to shoulder it.', 'society', '{"leaf":"has_technology","value":"tech_selected_lineages"}', NULL, 10);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('leader_enhancement_natural_selection', 'leader_enhancement', 'Natural Selection', 'Let nature take its course - it is in the crucible of experience that genius is forged.
Leaders gain no additional bonuses', NULL, NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('leader_enhancement_selected_lineages', 'leader_enhancement', 'Selected Lineages', 'Careful reproductive planning should be incentivized, lest we waste valuable genetic legacies.
While active our Empire gains:', NULL, '{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_fanatic_egalitarian"}]}', 1);
