INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('first_contact_protocol', 'First Contact Protocol', 'As we travel the stars there is a definite possibility of finding other lifeforms, and we need to have a clear stance on how to approach them.', 'diplomacy', '{"leaf":"always","value":"yes"}', NULL, 11);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('first_contact_proactive', 'first_contact_protocol', 'Proactive', 'Meeting alien civilizations presents an exciting opportunity to make new friends and fresh discoveries. We shall do our utmost to ensure that first contact happens smoothly, hailing unknown ships with a cordially-phrased greeting and a copy of our Official Standard Encyclopedia, along with its audio-visual companion dossier.
Cannot attack neutral entities
Other empires will find it easier to establish communications with us
Gain 50% more Influence from each successful first contact process', NULL, '{"op":"and","args":[{"leaf":"is_homicidal","value":"no"},{"leaf":"is_xenophobe","value":"no"},{"op":"not","args":[{"leaf":"has_origin","value":"origin_payback"}]}]}', 0);
INSERT INTO tradition_modifier
                   (owner_key, modifier_key, modifier_value, potential_json, sort_order)
                   VALUES ('first_contact_proactive', 'first_contact_speed_mult', '0.1', NULL, 0);
INSERT OR REPLACE INTO modifier_label (modifier_key, label, positive_is_good)
           VALUES ('first_contact_speed_mult', 'First Contact Speed', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('first_contact_cautious', 'first_contact_protocol', 'Cautious', 'We will take every measure to prevent information about ourselves from falling into alien hands before we have decided whether they will be friend or foe.
Cannot attack neutral entities
Other nations will find it harder to establish communications with us
Negative first contact events are less likely to happen to us', NULL, '{"leaf":"is_homicidal","value":"no"}', 1);
INSERT INTO tradition_modifier
                   (owner_key, modifier_key, modifier_value, potential_json, sort_order)
                   VALUES ('first_contact_cautious', 'first_contact_defense_add', '2.0', NULL, 0);
INSERT OR REPLACE INTO modifier_label (modifier_key, label, positive_is_good)
           VALUES ('first_contact_defense_add', 'First Contact Target Difficulty', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('first_contact_attack_allowed', 'first_contact_protocol', 'Aggressive', 'Unknown dangers may hide among the stars. To ensure our continued survival we must be ready to strike without hesitation.
Can attack neutral entities
Enables hostile first contact options, such as abduction and dissection', NULL, '{"op":"and","args":[{"leaf":"is_pacifist","value":"no"},{"op":"or","args":[{"leaf":"is_xenophile","value":"no"},{"leaf":"is_homicidal","value":"yes"}]}]}', 2);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('border_policy', 'Initial Border Status', 'The borders of our empire represent our very grasp on the galaxy itself. We must decide if they are to be open and welcoming or shut and guarded to other civilizations we might encounter.', 'diplomacy', '{"leaf":"is_nomadic","value":"no"}', NULL, 12);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('border_policy_open', 'border_policy', 'Open', 'Isolation invites suspicion, and suspicion invites conflict. Let us show our neighbors that we have nothing to hide.
Borders will be open to other empires by default.', '{"op":"or","args":[{"leaf":"is_country_type","value":"default"},{"leaf":"is_country_type","value":"mirrored_country"},{"leaf":"is_primitive","value":"yes"}]}', '{"op":"or","args":[{"leaf":"is_nomadic","value":"yes"},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_valid_civic","value":"civic_machine_terminator"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"}]}]},{"leaf":"is_primitive","value":"yes"}]}', 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('border_policy_closed', 'border_policy', 'Closed', 'The borders of our empire must be well guarded, lest we fall victim to insidious influences. Only those who have proven themselves worthy may enter our space.
Borders will be closed to other empires by default.', '{"leaf":"is_nomadic","value":"no"}', '{"leaf":"is_primitive","value":"no"}', 1);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('food_policy', 'Food Policy', 'Our empire has a plethora of hungry mouths to feed. To ensure food security does not become a problem, we must balance the needs of the population with our need for growth.', 'economy', '{"leaf":"always","value":"no"}', NULL, 13);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('food_policy_rationing', 'food_policy', 'Strict Rationing', 'In times of need, we all must sacrifice for the greater good. What is a little starvation now, when our glorious future awaits?', NULL, NULL, 0);
INSERT INTO tradition_modifier
                   (owner_key, modifier_key, modifier_value, potential_json, sort_order)
                   VALUES ('food_policy_rationing', 'planet_pops_organics_food_upkeep_mult', '-0.25', NULL, 0);
INSERT OR REPLACE INTO modifier_label (modifier_key, label, positive_is_good)
           VALUES ('planet_pops_organics_food_upkeep_mult', 'Pop Food Upkeep', 0);
