INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('trade_policy_consumer_goods', 'trade_policy', 'Consumer Benefits', 'Profits and taxes must take second place to improving the lives of our citizens. We should focus our trade efforts towards the manufacture and distribution of everyday necessities.
50% of our collected Trade earns us Consumer Goods. Every Trade 1 earns us Consumer Goods 0.5.', '{"op":"and","args":[{"op":"or","args":[{"leaf":"has_federation","value":"no"},{"op":"and","args":[{"leaf":"has_federation","value":"yes"},{"leaf":"federation","value":"scope"}]}]},{"leaf":"has_tradition","value":"tr_mercantile_adaptive_economic_policies"},{"leaf":"is_worker_coop_empire","value":"no"}]}', NULL, 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('trade_policy_unity', 'trade_policy', 'Marketplace of Ideas', 'Trade can be used not only to move goods around, but also to facilitate the spread of ideas. We should focus our trade efforts towards ensuring that the message of our government is heard on all colonies where we do business.
50% of our collected Trade earns us Unity. Every Trade 1 earns us Unity 0.25.', '{"op":"and","args":[{"op":"or","args":[{"leaf":"has_federation","value":"no"},{"op":"and","args":[{"leaf":"has_federation","value":"yes"},{"leaf":"federation","value":"scope"}]}]},{"leaf":"has_tradition","value":"tr_mercantile_adaptive_economic_policies"},{"leaf":"is_worker_coop_empire","value":"no"}]}', NULL, 2);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('trade_policy_trade_league', 'trade_policy', 'Trade League', 'By banding together in a trade league, we are able to prosper and secure profits on a whole new level.
50% of our collected Trade earns us Energy Credits, Unity, and Consumer Goods. Every Trade 1 earns us Energy 0.3, Unity 0.15, and Consumer Goods 0.3.', '{"op":"and","args":[{"leaf":"has_federation","value":"yes"},{"leaf":"federation","value":"scope"}]}', NULL, 3);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('trade_policy_holy_covenant', 'trade_policy', 'Holy Covenant', 'By banding together in a holy covenant, we may bask in the collective glory of our divine purpose.
50% of our collected Trade earns us Unity. Every Trade 1 earns us Unity 0.375.', '{"op":"and","args":[{"leaf":"has_federation","value":"yes"},{"leaf":"federation","value":"scope"}]}', NULL, 4);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('trade_policy_mutual_aid', 'trade_policy', 'Mutual Aid', 'By reinvesting our surplus back into the cooperative, we ensure that all our members may thrive according to their needs and shared aspirations.
75% each of our collected Trade earns us Energy Credits, Minerals, Food, and Unity. Every Trade 1 earns us Energy 0.27, Minerals 0.27, Food 0.27, and Unity 0.1.', '{"leaf":"is_worker_coop_empire","value":"yes"}', NULL, 5);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('logistics_policy', 'Logistics Policy', 'The trade network can be monopolized for logistic needs, to efficiently shift resources and gear around.', 'economy', '{"leaf":"is_gestalt","value":"yes"}', NULL, 21);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('logistics_policy_gestalt', 'logistics_policy', 'Logistics Policy', 'Drones will diligently carry supplies and resources wherever we need them.', '{"leaf":"is_gestalt","value":"yes"}', NULL, 0);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('drone_policy', 'Production Policy', 'The synaptic capabilities of our vast Mind are immense, but not limitless. We must decide where to best put these cerebral resources to use.', 'economy', '{"op":"and","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"},{"leaf":"is_wilderness_empire","value":"no"}]}', NULL, 22);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('drone_policy_balanced', 'drone_policy', 'Balanced Production', 'The Mind dedicates itself equally to the production of raw resources and finished goods.
No bonuses or penalties to resource production.', NULL, NULL, 0);
