                   potential_json, valid_json, sort_order) VALUES ('drone_policy_worker', 'drone_policy', 'Extraction Focus', 'The Menial Drones that extract raw resources are given priority by the Mind, becoming more productive at the expense of the Complex Drones.', NULL, NULL, 1);
