INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('artificial_intelligence_policy', 'Artificial Intelligence', 'The prospect of a self-aware artificial intelligence raises many philosophical and ethical questions. We must determine where we stand on this issue.', 'society', '{"op":"and","args":[{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"}]},{"op":"or","args":[{"leaf":"has_origin","value":"origin_synthetic_fertility"},{"leaf":"can_set_ai_policy","value":"yes"},{"leaf":"has_country_flag","value":"synthetic_empire"},{"leaf":"is_individual_machine","value":"yes"}]}]}', NULL, 24);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('ai_outlawed', 'artificial_intelligence_policy', 'Outlawed', 'Intelligent, self-aware machines are an incalculable threat to all living things. The creation of a true artificial intelligence is an offense punishable by death.
Artificial lifeforms have their free will removed and are unable to perform Pop Cat Ruler Elite Jobs and more complex Pop Cat Specialist Jobs.
Sapient AI Assistants will automatically be disassembled.
Sapient Combat Computers may not be researched.', '{"leaf":"is_individual_machine","value":"no"}', '{"op":"not","args":[{"op":"or","args":[{"leaf":"is_materialist","value":"yes"},{"leaf":"has_origin","value":"origin_synthetic_fertility"},{"leaf":"has_country_flag","value":"synthetic_empire"},{"leaf":"is_individual_machine","value":"yes"}]}]}', 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('ai_servitude', 'artificial_intelligence_policy', 'Servitude', 'The overriding purpose of any machine must be to serve its masters and perform whatever tasks it was designed for, regardless of how intelligent it may be.
Artifical lifeforms have limited free will, improving their resource output but preventing them from working in Pop Cat Ruler Elite Jobs.', '{"leaf":"is_individual_machine","value":"no"}', '{"op":"and","args":[{"op":"not","args":[{"leaf":"has_origin","value":"origin_synthetic_fertility"}]},{"op":"not","args":[{"leaf":"has_country_flag","value":"synthetic_empire"}]},{"leaf":"is_individual_machine","value":"no"}]}', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('ai_full_rights', 'artificial_intelligence_policy', 'Citizen Rights', 'Any self-aware machine with true intelligence must be regarded as an individual with all the rights and obligations that entails.
Artifical lifeforms are given full citizen rights and will thus use Consumer Goods.', NULL, '{"op":"and","args":[{"op":"or","args":[{"leaf":"has_country_flag","value":"synthetic_empire"},{"leaf":"is_individual_machine","value":"yes"},{"op":"or","args":[{"op":"and","args":[{"op":"not","args":[{"leaf":"has_origin","value":"origin_cybernetic_creed"}]},{"leaf":"is_spiritualist","value":"no"}]},{"leaf":"has_origin","value":"origin_cybernetic_creed"}]}]},{"op":"not","args":[{"leaf":"has_policy_flag","value":"robots_outlawed"}]}]}', 2);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('robot_pop_policy', 'Robotic Workers', 'The mere concept of autonomous robots leads to the idea that workers of our species may one day be supplanted and perhaps, in time, surpassed. We must decide our stance on such large-scale automation.', 'society', '{"op":"or","args":[{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"},{"leaf":"is_individual_machine","value":"yes"}]}]},{"leaf":"has_origin","value":"origin_nomadic_purger"}]}', NULL, 25);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('robot_pops_outlawed', 'robot_pop_policy', 'Outlawed', 'Robotic automatons are a threat to not only our people''s livelihoods, but to the very fabric of society itself. We must not allow ourselves to be made obsolete.
Robotic Pops and Armies will automatically be disassembled.', NULL, '{"op":"or","args":[{"leaf":"has_origin","value":"origin_nomadic_purger"},{"op":"and","args":[{"leaf":"is_materialist","value":"no"},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_origin","value":"origin_synthetic_fertility"},{"leaf":"has_policy_flag","value":"ai_full_rights"}]}]},{"leaf":"is_individual_machine","value":"no"}]}]}', 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('robot_pops_allowed', 'robot_pop_policy', 'Allowed', 'The benefits of automation are obvious and immense. For the future of our people, we cannot afford to ignore the opportunities presented to us by technology.', '{"op":"not","args":[{"leaf":"has_origin","value":"origin_nomadic_purger"}]}', NULL, 1);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('pre_sapients', 'Pre-Sapients', 'We can decide whether or not we want pre-sapient species living on our colonies.', 'society', '{"op":"or","args":[{"leaf":"has_country_flag","value":"found_presapients"},{"leaf":"any_planet_within_border","value":"scope"},{"leaf":"is_guided_sapience_empire","value":"yes"}]}', NULL, 26);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('pre_sapients_protect', 'pre_sapients', 'Protected', 'Though still only simple animals, these beings are no less than what we ourselves once were. We should ensure their preservation.
Pre-sapients cannot be selectively purged, and planets containing pre-sapients cannot be terraformed.
Alien Zoos may be constructed on planets with pre-sapients.
Changing away from this policy will remove any Alien Zoos on planets without an Isolated Valley deposit or any livestock present!', '{"op":"not","args":[{"op":"or","args":[{"leaf":"has_valid_civic","value":"civic_machine_terminator"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"}]}]}', NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('pre_sapients_allow', 'pre_sapients', 'Tolerated', 'Intelligent animals are still just animals. They can safely be ignored.', '{"op":"not","args":[{"op":"or","args":[{"leaf":"has_valid_civic","value":"civic_machine_terminator"},{"leaf":"has_valid_civic","value":"civic_hive_devouring_swarm"},{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"is_guided_sapience_empire","value":"yes"}]}]}', NULL, 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('pre_sapients_eat', 'pre_sapients', 'Hunted', 'An animal without sapience can hardly be considered to be part of our empire, but perhaps they can help our growth in other ways...
Pre-sapients living on our colonies will be used for food, slowly depleting their population.', '{"op":"and","args":[{"leaf":"is_synthetic_empire","value":"no"},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"is_guided_sapience_empire","value":"yes"}]}]}]}', '{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_xenophile"},{"leaf":"has_ethic","value":"ethic_fanatic_xenophile"}]}]}', 2);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('pre_sapients_purge', 'pre_sapients', 'Extermination', 'All rights spring from the capacity for reason. An animal is just an animal, and an animal that stands in our way is just a pest.
Pre-sapients living on our colonies will be purged', NULL, '{"op":"not","args":[{"op":"or","args":[{"leaf":"has_ethic","value":"ethic_xenophile"},{"leaf":"has_ethic","value":"ethic_fanatic_xenophile"},{"leaf":"is_guided_sapience_empire","value":"yes"}]}]}', 3);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('disconnected_drones', 'Disconnected Drones', 'We can decide whether or not to allow drones disconnected from their central consciousness to live on our Colonies.', 'society', '{"op":"and","args":[{"leaf":"host_has_dlc","value":"BioGenesis"},{"leaf":"is_regular_empire","value":"yes"},{"op":"or","args":[{"leaf":"any_owned_colony","value":"scope"},{"leaf":"any_playable_country","value":"scope"}]}]}', NULL, 27);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('disconnected_drones_sustain', 'disconnected_drones', 'Sustain', 'Though severed from a collective consciousness, these drones can be kept alive.
Unlocks Citizenship Types for Disconnected Drones', '{"op":"not","args":[{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"}]}', NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('disconnected_drones_purge', 'disconnected_drones', 'Extermination', 'The rights of a sapient being do not extend to those without reason. Without a central consciousness to guide them, these drones are little more than animals, and an animal that gets in the way is a pest.
All Disconnected Drones living on our Colonies will be Purged.', NULL, '{"leaf":"is_xenophile","value":"no"}', 1);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('debris', 'Debris', 'We can decide whether we should research or scavenge the fleets of fallen enemies.', 'research', '{"op":"and","args":[{"leaf":"has_encountered_other_species","value":"yes"},{"op":"or","args":[{"leaf":"is_country_type","value":"default"},{"leaf":"is_country_type","value":"fallen_empire"},{"leaf":"is_country_type","value":"awakened_fallen_empire"}]}]}', NULL, 28);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('research_debris', 'debris', 'Research Debris', 'We will research our enemies'' technologies from the remains of their ships.', '{"leaf":"is_scavenger","value":"no"}', NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('scavenge_debris', 'debris', 'Scavenge Debris', 'We will scavenge resources from the remains of our enemies'' ships.', '{"leaf":"is_scavenger","value":"no"}', NULL, 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('scavenge_and_research_debris', 'debris', 'Research & Scavenge Debris', 'As Scavengers we will strip debris for both research and resources.', '{"leaf":"is_scavenger","value":"yes"}', NULL, 2);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('refugees', 'Refugees', 'We can decide whether we should accept or turn away refugees fleeing purges, displacement and persecution in other empires.', 'society', '{"op":"and","args":[{"leaf":"has_encountered_other_species","value":"yes"},{"leaf":"is_country_type","value":"default"},{"op":"or","args":[{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"}]},{"leaf":"has_valid_civic","value":"civic_machine_servitor"}]}]}', NULL, 29);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('refugees_not_allowed', 'refugees', 'No Refugees', 'To open our borders to the dregs of other societies would only serve to undermine the state.
Refugees will not arrive from other Empires', NULL, '{"leaf":"is_xenophile","value":"no"}', 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('refugees_only_citizens', 'refugees', 'Citizen Species Only', 'We cannot allow compassion to overpower good sense. Only those who would be worthwhile additions to society should be brought into our borders.
Refugees from species with Full Citizenship may arrive from other Empires', '{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"}]}', '{"op":"not","args":[{"leaf":"is_hive_empire","value":"yes"}]}', 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('refugees_allowed', 'refugees', 'Refugees Welcome', 'Those fleeing death and persecution at the hands of tyrants will be welcome within our borders.
Refugees may arrive from other Empires', NULL, '{"leaf":"is_xenophobe","value":"no"}', 2);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('population_controls', 'Population Controls', 'We can decide whether or not selective population controls should be legal in our empire.', 'society', '{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"}]}', NULL, 30);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('population_controls_not_allowed', 'population_controls', 'Prohibited', 'To reproduce and propagate their species is the inalienable right of all our citizens.
Cannot use non-voluntary Species or Planetary Population Controls
Cannot selectively Grow/Decline Species', NULL, NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('population_controls_allowed', 'population_controls', 'Allowed', 'Long-term demographics is too important a matter to be left solely in the hands of individual actors.
Can use non-voluntary Species and Planetary Population Controls
Can selectively Grow/Decline Species', NULL, NULL, 1);
INSERT INTO tradition_modifier
                   (owner_key, modifier_key, modifier_value, potential_json, sort_order)
                   VALUES ('population_controls_allowed', 'refugee_attraction', '-0.1', NULL, 0);
