           VALUES ('refugee_attraction', 'Refugee Attraction', 1);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('slavery', 'Slavery', 'We can decide whether or not slavery should be legal in our empire.', 'society', '{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"}]}', NULL, 31);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('slavery_not_allowed', 'slavery', 'Prohibited', 'The enslavement of sapient beings is an abomination and will not be tolerated within our Empire.
Can not Enslave Pops', NULL, '{"op":"not","args":[{"op":"or","args":[{"leaf":"has_valid_civic","value":"civic_slaver_guilds"},{"leaf":"has_valid_civic","value":"civic_indentured_assets"}]}]}', 0);
INSERT INTO tradition_modifier
                   (owner_key, modifier_key, modifier_value, potential_json, sort_order)
                   VALUES ('slavery_not_allowed', 'slave_market_cost_mult', '1.0', NULL, 0);
