                   potential_json, valid_json, sort_order) VALUES ('slavery_allowed', 'slavery', 'Allowed', 'Allows the enslavement of Pops within our Empire.
Can Enslave Pops', NULL, '{"op":"and","args":[{"op":"not","args":[{"leaf":"any_agreement","value":"scope"}]},{"op":"not","args":[{"leaf":"has_origin","value":"origin_broken_shackles"}]},{"op":"or","args":[{"leaf":"is_authoritarian","value":"yes"},{"leaf":"is_xenophobe","value":"yes"}]}]}', 1);
