           VALUES ('refugee_attraction', 'Refugee Attraction', 1);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('purge', 'Purge', 'Purged Pops are unable to work and will ultimately perish, but the process will enrage them as well as any sympathetic Pops.', 'society', NULL, NULL, 32);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('purge_not_allowed', 'purge', 'Prohibited', 'The Purge is an atrocity and should always be treated as such.
Can not Purge Pops', NULL, '{"op":"and","args":[{"op":"not","args":[{"leaf":"has_ethic","value":"ethic_gestalt_consciousness"}]},{"op":"not","args":[{"op":"or","args":[{"leaf":"has_valid_civic","value":"civic_fanatic_purifiers"},{"leaf":"has_valid_civic","value":"civic_scorched_earth"},{"leaf":"has_origin","value":"origin_nomadic_purger"}]}]}]}', 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('purge_displacement_only', 'purge', 'Displacement Only', 'It is not our responsibility to see to the needs of those who would undermine the foundations of our society. Let them find their homes outside our borders.
Can Displace Pops', NULL, '{"op":"and","args":[{"leaf":"is_xenophile","value":"no"},{"leaf":"is_homicidal","value":"no"},{"op":"not","args":[{"op":"and","args":[{"leaf":"has_origin","value":"origin_nomadic_purger"},{"leaf":"overlord?","value":"scope"}]}]}]}', 1);
INSERT INTO tradition_modifier
                   (owner_key, modifier_key, modifier_value, potential_json, sort_order)
                   VALUES ('purge_displacement_only', 'refugee_attraction', '-0.25', NULL, 0);
