INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('nomad_total_war_subject', 'nomad_total_war', 'Subjugate', 'Newly conquered land should be ruled by a subject loyal to us.
