INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('nomad_total_war_displace', 'nomad_total_war', 'Displace', 'Alien life deserves to keep existing, but the planets near us really should be vacated.
