INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('relentless_industrialists_policy', 'Industrialism', 'To live is to exploit. But to exploit to the degree that we practice it has consequences. We can choose to channel our energies towards the attainment of more, or seek to mitigate its worst effects.', 'economy', '{"op":"and","args":[{"leaf":"is_country_type","value":"default"},{"leaf":"is_relentless_industrialist_empire","value":"yes"},{"leaf":"has_country_flag","value":"relentless_industrialists_situation_finished"}]}', NULL, 35);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('relentless_industrialists_full_steam_ahead', 'relentless_industrialists_policy', 'Full Steam Ahead', 'Our industries shall not suffer any constraints.
Increased output bonuses from Coordinated Fulfillment Center.', NULL, NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('relentless_industrialists_study', 'relentless_industrialists_policy', 'For Science!', 'There is much to learn from the process of irradiating a planet.
Allows us to terraform planets into Tomb Worlds.
Reduced habitability penalties from Coordinated Fulfillment Center.', NULL, NULL, 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('relentless_industrialists_cleanup', 'relentless_industrialists_policy', 'Cleanup', 'We shall take steps to mitigate our environmental footprint.
Planets with Coordinated Fulfillment Center will no longer turn into Tomb Worlds over time, but the building will now cost a Unity upkeep.', NULL, NULL, 2);
INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('synthetic_identities_policy', 'Synthetic Identities', 'New synthetic identities must be created for us to multiply.', 'society', '{"leaf":"has_technology","value":"tech_identity_copy"}', NULL, 36);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('identity_copy', 'synthetic_identities_policy', 'Identity Copies', 'We will be able to copy the identity and memories of a Synthetic into a new mechanical body. The copies have predictable skill sets but make for stale conversation.
The copies experience only mild gloom from their lack of uniqueness., Mechanical Pops, Happiness: -5%
Identity Copies is used when assembling Synthetics', NULL, '{"leaf":"has_technology","value":"tech_identity_copy"}', 0);
