INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('computation_core_allocation', 'Computation Core Focus', 'Synthesized corporations can divert computation cycles from their core systems to optimize high-value societal sectors with zero delay.', 'society', '{"leaf":"is_synth_corporate","value":"yes"}', NULL, 37);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('computation_core_production', 'computation_core_allocation', 'Production Streamlining', 'Utilize spare processing cycles to streamline production processes.
Effects:
Every 100 Roboticists and Identity Designers increases Job Efficiency for Metallurgists and Artisans by +2.5%', NULL, NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('computation_core_stability', 'computation_core_allocation', 'Stability Analysis', 'Allocate resources for monitoring societal information flow for irregularities.
