INSERT INTO policy (key, name, description, category, potential_json, allow_json,
               sort_order) VALUES ('cyberization_standards', 'Cyberization Standards', 'Population-wide implants are necessary for our society, but those against full cyberization may opt for limited augmentation.', 'society', '{"op":"or","args":[{"leaf":"has_country_flag","value":"cyber_force_objectors"},{"leaf":"has_country_flag","value":"cyber_allow_objectors"},{"leaf":"has_country_flag","value":"cyber_hive_standards"}]}', NULL, 38);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('cyberization_standards_full', 'cyberization_standards', 'Full Cyberization', 'All individuals are expected to undergo the installation of a complete set of cybernetic implants.
Cybernetic Spiritualist Leader Trait: Cyborg
Cybernetic Spiritualist Pops benefit from Job Efficiency for Cybernetic Pops', '{"leaf":"is_gestalt","value":"no"}', NULL, 0);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('cyberization_standards_limited', 'cyberization_standards', 'Limited Cyberization', 'Individuals against full augmentation can install a limited set of cybernetic implants.
Cybernetic Spiritualist Leader Trait: Limited Cyborg
Cybernetic Spiritualist Pops do not benefit from Job Efficiency for Cybernetic Pops', '{"leaf":"is_gestalt","value":"no"}', NULL, 1);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('cyberization_standards_full_hive', 'cyberization_standards', 'Full Cyberization', 'Culling drones with bodies that reject cybernetic implants is a sacrifice made for greater efficiency.
Cybernetic Drones fully benefit from Job Efficiency for Cybernetic Pops, but suffer -5% Pop Growth Speed.', '{"leaf":"is_gestalt","value":"yes"}', NULL, 2);
INSERT INTO policy_option (key, policy_key, name, description,
                   potential_json, valid_json, sort_order) VALUES ('cyberization_standards_limited_hive', 'cyberization_standards', 'Limited Cyberization', 'Outfitting defective drones with limited cybernetic implants allows them to continue to contribute.
Job Efficiency for Cybernetic Drones: -5%', '{"leaf":"is_gestalt","value":"yes"}', NULL, 3);
