                   (key, name, description, days, department, outcomes_json)
                   VALUES ('IRASSIAN_ARCHEOLOGY_6', 'Mining Base', 'The deep boreholes on indicate the former presence of an Irassian mining base. Our archaeologists would like to investigate them further.', 180, 'society_technology', '[{"event": "precursor.1531", "name": null}, {"event": "ancrel.15055", "name": null}]');
INSERT OR REPLACE INTO special_project
                   (key, name, description, days, department, outcomes_json)
                   VALUES ('IRASSIAN_ARCHEOLOGY_7', 'Colony Remnants', 'was an early victim of the Javorian Pox, and our archaeologists would like to study the former Irassian colony for clues as to the origin of the disease.', 180, 'society_technology', '[{"event": "precursor.1536", "name": null}, {"event": "ancrel.15055", "name": null}]');
