                   VALUES ('DENDRITIAN_CHRONICLES_PROJECT_MACHINE', 'Study the Dendritian Chronicles', 'By studying the \', NULL, NULL, NULL);
INSERT OR REPLACE INTO special_project
                   (key, name, description, days, department, outcomes_json)
                   VALUES ('RESTORE_HYPERLANE_PROJECT', 'Restore Degraded Hyperlane', 'If we can find a way to restore the degraded hyperlane in , we will be able to confirm the existence of New Bratulla, the paradise planet sought by the Dendritians.', 180, NULL, '[{"event": "extreme_frontiers.1426", "name": null}]');
INSERT OR REPLACE INTO special_project
                   (key, name, description, days, department, outcomes_json)
                   VALUES ('GEORADIATION_SIGNAL_1_PROJECT', 'Signal Trace:', 'An identical communications frequency to the one emitted by the construct found on has been traced to this site, where another damaged device has been located. Studying it will yield further insight into their destructive terraforming capabilities.', 160, NULL, '[{"event": "extreme_frontiers.1515", "name": null}]');
INSERT OR REPLACE INTO special_project
                   (key, name, description, days, department, outcomes_json)
                   VALUES ('GEORADIATION_SIGNAL_2_PROJECT', 'Signal Trace:', 'The communications frequency emitted by the construct found on has also been traced to this site, where another damaged device has been located. Studying it will yield further insight into their destructive terraforming capabilities.', 160, NULL, '[{"event": "extreme_frontiers.1520", "name": null}]');
INSERT OR REPLACE INTO special_project
                   (key, name, description, days, department, outcomes_json)
                   VALUES ('UNDETONATED_GEORADIATION_PROJECT', 'Undetonated Device', 'We have located a fourth, as yet undetonated terraforming device on . Recovering it will fill the gaps in our understanding of this technology.', 160, NULL, '[{"event": "extreme_frontiers.1525", "name": null}]');
INSERT OR REPLACE INTO special_project
                   (key, name, description, days, department, outcomes_json)
